return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ta_IN','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-08T20:37:32+00:00','po-revision-date'=>'2026-09-08T20:37:32+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'வேர்ட்ஸ்பிரஸ் (WordPress)-க்கான முழுமையான கேச்சிங் மற்றும் ஆப்டிமைசேஷன் என்ஜின்: முழுப் பக்க கேச், ஆப்ஜெக்ட் கேச், டேட்டாபேஸ் கிளீனப் மற்றும் CSS/JS ஆப்டிமைசேஷன். உங்கள் ஹோஸ்ட் சொந்தமாகக் கேச் லேயரை வழங்காத போது இதனை நிறுவவும் - Zinn Digital® ஹோஸ்டிங்கில் அதற்குப் பதிலாக Zinn® Cache-ஐ நிறுவவும். முழுப் பக்க கேச்சிங் செய்வதற்கு LSCache மாடியூல் கொண்ட LiteSpeed அல்லது OpenLiteSpeed சர்வர் தேவை. LiteSpeed Cache செருகுநிரலின் GPLv3 ஃபோர்க்.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d மணிநேரம்','%d hour'=>'%d மணி நேரம்','%d minutes'=>'%d நிமிடங்கள்','%d minute'=>'%d நிமிடம்','Purged All!'=>'அனைத்தும் அகற்றப்பட்டன!','Purged the blog!'=>'வலைப்பதிவு அழிக்கப்பட்டது!','Purged the URL!'=>'URL நீக்கப்பட்டுவிட்டது!','Purged!'=>'அகற்றப்பட்டது!','Failed to upgrade.'=>'மேம்படுத்துவது தோல்வியடைந்தது.','Upgraded successfully.'=>'வெற்றிகரமாக மேம்படுத்தப்பட்டது.','Dashboard'=>'டாஷ்போர்டு','OptimaX'=>'OptimaX','Presets'=>'முன்னமைவுகள்','General'=>'பொதுவான','Cache'=>'நினைவகம்','CDN'=>'CDN','Image Optimization'=>'பட உகப்பாக்கம்','Page Optimization'=>'பக்க உகப்பாக்கம்','Database'=>'தரவுத்தளம்','Crawler'=>'கிராலர்','Toolbox'=>'கருவிப்பெட்டி','Cookie Name'=>'கக்கி பெயர்','Cookie Values'=>'குககி மதிப்புகள்','Remove cookie simulation'=>'குக்கி உருவகப்படுத்துதலை நீக்கு','Add new cookie to simulate'=>'போலியாக உருவாக்க புதிய குக்கியைச் சேர்','CDN URL to be used. For example, %s'=>'பயன்படுத்த வேண்டிய CDN URL. உதாரணமாக, %s','Remove CDN URL'=>'CDN URL-ஐ அகற்று','Add new CDN URL'=>'புதிய CDN URL ஐ சேர்','ON'=>'இயக்கம்','OFF'=>'ஆஃப்','Settings'=>'அமைப்புகள்','Dismiss'=>'நிராகரி','Save Changes'=>'மாற்றங்களைச் சேமிக்கவும்','This value is overwritten by the %s variable.'=>'இந்த மதிப்பு %s மாறியால் மேலெழுதப்படுகிறது.','This value is overwritten by the filter.'=>'இந்த மதிப்பு வடிப்பானால் மேலெழுதப்படுகிறது.','This value is overwritten by the PHP constant %s.'=>'இந்த மதிப்பு %s என்ற PHP மாறிலியால் மேலெழுதப்படுகிறது.','This value is overwritten by the primary site setting.'=>'இந்த மதிப்பு முதன்மைத் தள அமைப்பால் மேலெழுதப்படுகிறது.','This value is overwritten by the Network setting.'=>'இந்த மதிப்பு நெட்வொர்க் அமைப்பால் மேலெழுதப்படுகிறது.','Currently set to %s'=>'தற்போது %s என அமைக்கப்பட்டுள்ளது','Value from filter applied'=>'வடிகட்டியிலிருந்து பெறப்பட்ட மதிப்பு','seconds'=>'நொடிகள்','Default value'=>'இயல்பு மதிப்பு','Invalid rewrite rule'=>'தவறான ரீரைட் விதி','Path must end with %s'=>'பாதை %s இல் முடிய வேண்டும்','Minimum value'=>'குறைந்தபட்ச மதிப்பு','Maximum value'=>'அதிகபட்ச மதிப்பு','Zero, or'=>'பூஜ்யம், அல்லது','Larger than'=>'இதை விடப் பெரியது','Smaller than'=>'சிறியது','Value range'=>'மதிப்பு வரம்பு','Invalid IP'=>'தவறான ஐபி','API'=>'ஏபிஐ','Server variable(s) %s available to override this setting.'=>'இந்த அமைப்பை மீற %s சர்வர் மாறி(கள்) கிடைக்கின்றன.','The URLs will be compared to the REQUEST_URI server variable.'=>'URLகள் REQUEST_URI சேவையக மாறியுடன் (server variable) ஒப்பிடப்படும்.','For example, for %1$s, %2$s can be used here.'=>'உதாரணமாக, %1$s-க்கு, %2$s-ஐ இங்கு பயன்படுத்தலாம்.','To match the beginning, add %s to the beginning of the item.'=>'தொடக்கத்துடன் பொருத்த, உருப்படியின் தொடக்கத்தில் %s ஐச் சேர்க்கவும்.','To do an exact match, add %s to the end of the URL.'=>'துல்லியமான பொருத்தத்தைப் பெற, URL-ன் முடிவில் %s ஐச் சேர்க்கவும்.','One per line.'=>'வரிக்கு ஒன்று.','%s groups'=>'%s குழுக்கள்','%s images'=>'%s படங்கள்','%s group'=>'%s குழு','%s image'=>'%s படம்','No fields'=>'புலங்கள் இல்லை','The user with id %s has editor access, which is not allowed for the role simulator.'=>'%s ஐடி கொண்ட பயனர் எடிட்டர் அணுகலைக் கொண்டுள்ளார், இது ரோல் சிமுலேட்டருக்கு அனுமதிக்கப்படாது.','Options saved.'=>'விருப்பத்தேர்வுகள் சேமிக்கப்பட்டன.','Notified Cloudflare to set development mode to %s successfully.'=>'Cloudflare இல் டெவலப்மென்ட் மோடை %s ஆக வெற்றிகரமாக அமைக்க அறிவிக்கப்பட்டது.','Cloudflare API is set to off.'=>'Cloudflare API ஆஃப் செய்யப்பட்டுள்ளது.','Notified Cloudflare to purge all successfully.'=>'வெற்றிகரமாக அகற்ற Cloudflare அறிவிக்கப்பட்டது.','No available Cloudflare zone'=>'கிடைக்கப்பெறாத Cloudflare zone','Failed to communicate with Cloudflare'=>'Cloudflare உடன் தொடர்பு கொள்வதில் தோல்வி ஏற்பட்டது','Communicated with Cloudflare successfully.'=>'Cloudflare உடன் வெற்றிகரமாகத் தொடர்பு கொள்ளப்பட்டது.','Failed to validate %s activation data.'=>'%s செயல்படுத்துதல் தரவைச் சரிபார்ப்பது தோல்வியடைந்தது.','Failed to parse %s activation status.'=>'%s இன் செயல்படுத்துதல் நிலையைக் குறியீடு நீக்கம் செய்வதில் தோல்வி.','%s activation data expired.'=>'%s செயல்படுத்தd தரவு காலாவதியாகிவிட்டது.','Congratulations, %s successfully set this domain up for the anonymous online services.'=>'வாழ்த்துக்கள், %s இந்த டொமைனை அநாமதேய ஆன்லைன் சேவைகளுக்காக வெற்றிகரமாக அமைத்துள்ளது.','Congratulations, %s successfully set this domain up for the online services.'=>'வாழ்த்துக்கள், %s இந்த டொமைனை ஆன்லைன் சேவைகளுக்காக வெற்றிகரமாக அமைத்துள்ளது.','Congratulations, %s successfully set this domain up for the online services with CDN service.'=>'வாழ்த்துகள், CDN சேவையுடன் ஆன்லைன் சேவைகளுக்காக %s இந்த டொமைனை வெற்றிகரமாக அமைத்துவிட்டது.','Site not recognized. QUIC.cloud deactivated automatically. Please reactivate your QUIC.cloud account.'=>'தளம் அடையாளம் காணப்படவில்லை. QUIC.cloud தானாகவே முடக்கப்பட்டது. உங்கள் QUIC.cloud கணக்கை மீண்டும் இயக்கவும்.','Click here to proceed.'=>'தொடர இங்கே சொடுக்கவும்.','QUIC.cloud\'s access to your WP REST API seems to be blocked.'=>'QUIC.cloud இன் உங்கள் WP REST APIக்கான அணுகல் தடுக்கப்பட்டுள்ளதாகத் தெரிகிறது.','Failed to get echo data from WPAPI'=>'WPAPI இலிருந்து எக்கோ (echo) தரவைப் பெறுவதில் தோல்வி ஏற்பட்டது','You need to set the %1$s first. Please use the command %2$s to set.'=>'முதலில் நீங்கள் %1$s ஐ அமைக்க வேண்டும். அமைக்க தயவுசெய்து %2$s கட்டளையைப் பயன்படுத்தவும்.','Server IP'=>'சர்வர் ஐபி','You need to activate QC first.'=>'நீங்கள் முதலில் QC ஐ இயக்க வேண்டும்.','Cert or key file does not exist.'=>'சான்றிதழ் அல்லது விசை கோப்பு இல்லை.','Reset %s activation successfully.'=>'%s செயல்படுத்தல் வெற்றிகரமாக மீட்டமைக்கப்பட்டது.','Linked to QUIC.cloud preview environment, for testing purpose only.'=>'QUIC.cloud முன்னோட்ட சூழலுடன் இணைக்கப்பட்டுள்ளது, சோதனை நோக்கத்திற்காக மட்டுமே.','Cloud Error'=>'மேகப் பிழை','No available Cloud Node after checked server load.'=>'சேவையகச் சுமையைச் சரிபார்த்த பிறகு கிளவுட் நோட் எதுவும் கிடைக்கவில்லை.','No available Cloud Node.'=>'கிடைக்கக்கூடிய கிளவுட் நோடு எதுவும் இல்லை.','In order to use QC services, need a real domain name, cannot use an IP.'=>'QC சேவைகளைப் பயன்படுத்த, உண்மையான டொமைன் பெயர் தேவை, ஐபி (IP) முகவரியைப் பயன்படுத்த முடியாது.','Please try after %1$s for service %2$s.'=>'சேவை %2$s-க்கான கோரிக்கையை தயவுசெய்து %1$s கழித்து முயற்சிக்கவும்.','Failed to request via WordPress'=>'WordPress வழியாக கோருவதில் தோல்வி ஏற்பட்டுள்ளது','Cloud server refused the current request due to unpulled images. Please pull the images first.'=>'இழுக்கப்படாத படங்கள் காரணமாக கிளவுட் சர்வர் தற்போதைய கோரிக்கையை நிராகரித்துள்ளது. தயவுசெய்து முதலில் படங்களை இழுக்கவும்.','Your domain_key has been temporarily blocklisted to prevent abuse. You may contact support at QUIC.cloud to learn more.'=>'முறைகேட்டைத் தவிர்ப்பதற்காக உங்கள் domain_key தற்காலிகமாக பிளாக்லிஸ்ட் செய்யப்பட்டுள்ளது. மேலும் அறிய நீங்கள் QUIC.cloud ஆதரவுக் குழுவைத் தொடர்பு கொள்ளலாம்.','Cloud server refused the current request due to rate limiting. Please try again later.'=>'விகித வரம்பு (rate limiting) காரணமாக கிளவுட் சேவையகம் தற்போதைய கோரிக்கையை நிராகரித்தது. சிறிது நேரம் கழித்து மீண்டும் முயற்சிக்கவும்.','Redetected node'=>'மறு கண்டறியப்பட்ட முனை','We are working hard to improve your online service experience. The service will be unavailable while we work. We apologize for any inconvenience.'=>'உங்கள் ஆன்லைன் சேவை அனுபவத்தை மேம்படுத்த நாங்கள் தீவிரமாக உழைத்து வருகிறோம். நாங்கள் பணிபுரியும் போது சேவை கிடைக்காது. இதனால் ஏற்படும் சிரமத்திற்கு வருந்துகிறோம்.','Message from QUIC.cloud server'=>'QUIC.cloud சேவையகத்திலிருந்து செய்தி','Good news from QUIC.cloud server'=>'QUIC.cloud சர்வரிலிருந்து நல்ல செய்தி','%1$s plugin version %2$s required for this action.'=>'இந்தச் செயலுக்கு %1$s செருகுநிரல் பதிப்பு %2$s தேவைப்படுகிறது.','Failed to communicate with QUIC.cloud server'=>'QUIC.cloud சேவையகத்துடன் தொடர்புகொள்வது தோல்வியடைந்தது','Sync QUIC.cloud status successfully.'=>'QUIC.cloud நிலை வெற்றிகரமாக ஒத்திசைக்கப்பட்டது.','Sync credit allowance with Cloud Server successfully.'=>'கிளவுட் சர்வரில் கிரெடிட் அளவை வெற்றிகரமாக ஒத்திசைக்கப்பட்டது.','Saving option failed. IPv4 only for %s.'=>'சேமிப்பு விருப்பம் தோல்வியடைந்தது. %s-க்கு IPv4 மட்டும்.','Changed setting successfully.'=>'அமைப்பு வெற்றிகரமாக மாற்றப்பட்டது.','Notified LiteSpeed Web Server to purge everything.'=>'அனைத்தையும் நீக்க LiteSpeed வெப் சர்வரகத்திற்கு அறிவிக்கப்பட்டது.','Notified LiteSpeed Web Server to purge the list.'=>'பட்டியலை அழிக்க LiteSpeed Web Server அறிவிக்கப்பட்டுள்ளது.','Sitemap cleaned successfully'=>'தள வரைபடம் வெற்றிகரமாக அகற்றப்பட்டது','No valid sitemap parsed for crawler.'=>'கிராவலருக்காக செல்லுபடியாகும் சைட்மேப் எதுவும் பகுப்பாய்வு செய்யப்படவில்லை.','Sitemap created successfully: %d items'=>'தள வரைபடம் வெற்றிகரமாக உருவாக்கப்பட்டது: %d உருப்படிகள்','Crawler disabled list is cleared! All crawlers are set to active! '=>'கிராலர் முடக்கப்பட்ட பட்டியல் அழிக்கப்பட்டது! அனைத்து கிராலர்களும் செயலில் உள்ளதாக அமைக்கப்பட்டுள்ளன!','Started async crawling'=>'ஒத்திசைவற்ற கிராவலிங் தொடங்கப்பட்டது','Guest'=>'விருந்தினர்','Manually added to blocklist'=>'தடுப்புப்பட்டியலில் கைமுறையாகச் சேர்க்கப்பட்டது','Previously existed in blocklist'=>'இதற்கு முன்பு தடுப்புப் பட்டியலில் இருந்தது','The database has been upgrading in the background since %s. This message will disappear once upgrade is complete.'=>'%s முதல் தரவுத்தளம் பின்னணியில் மேம்படுத்தப்பட்டு வருகிறது. மேம்படுத்தல் முடிந்ததும் இந்தச் செய்தி மறைந்துவிடும்.','Clean all successfully.'=>'அனைத்தும் வெற்றிகரமாக அழிக்கப்பட்டன.','Clean post revisions successfully.'=>'பதிவு திருத்தங்களை வெற்றிகரமாக சுத்தம் செய்தது.','Clean orphaned post meta successfully.'=>'கைவிடப்பட்ட இடுகை மெட்டாவை வெற்றிகரமாக சுத்தம் செய்யவும்.','Clean auto drafts successfully.'=>'தானியங்கு வரைவுகள் வெற்றிகரமாக அழிக்கப்பட்டன.','Clean trashed posts and pages successfully.'=>'அகற்றப்பட்ட இடுகைகளையும் பக்கங்களையும் வெற்றிகரமாக சுத்தம் செய்யவும்.','Clean spam comments successfully.'=>'ஸ்பேம் பின்னூட்டங்கள் வெற்றிகரமாக சுத்தம் செய்யப்பட்டன.','Clean trashed comments successfully.'=>'குப்பைத் தொட்டி கருத்துகள் வெற்றிகரமாக அழிக்கப்பட்டன.','Clean trackbacks and pingbacks successfully.'=>'டிராக்பேக்குகள் மற்றும் பிங்பேக்குகளை வெற்றிகரமாக சுத்தம் செய்யவும்.','Clean expired transients successfully.'=>'காலாவதியான தற்காலிக தரவுகள் வெற்றிகரமாக அழிக்கப்பட்டன.','Clean all transients successfully.'=>'அனைத்து தற்காலிகத் தரவுகளும் வெற்றிகரமாக அழிக்கப்பட்டன.','Optimized all tables.'=>'அனைத்து அட்டவணைகளும் உகந்ததாக்கப்பட்டுள்ளன.','Converted to InnoDB successfully.'=>'InnoDB ஆக வெற்றிகரமாக மாற்றப்பட்டது.','Invalid log type.'=>'தவறான பதிவுவகை.','Log file not found.'=>'பதிவுக் கோப்பு கிடைக்கவில்லை.','This setting is %1$s for certain qualifying requests due to %2$s!'=>'குறிப்பிட்ட தகுதி பெறும் கோரிக்கைகளுக்கு %2$s காரணமாக இந்த அமைப்பு %1$s ஆகும்!','This setting will regenerate crawler list and clear the disabled list!'=>'இந்த அமைப்பு கிராலர் பட்டியலை மீண்டும் உருவாக்கி, முடக்கப்பட்ட பட்டியலை அழிக்கும்!','This site utilizes caching in order to facilitate a faster response time and better user experience. Caching potentially stores a duplicate copy of every web page that is on display on this site. All cache files are temporary, and are never accessed by any third party, except as necessary to obtain technical support from the cache plugin vendor. Cache files expire on a schedule set by the site administrator, but may easily be purged by the admin before their natural expiration, if necessary. We may use QUIC.cloud services to process & cache your data temporarily.'=>'வேகமான பதில் நேரம் மற்றும் சிறந்த பயனர் அனுபவத்தை எளிதாக்குவதற்காக இந்தத் தளம் கேச்சிங்கைப் பயன்படுத்துகிறது. கேச்சிங் சாத்தியமான முறையில் இந்தத் தளத்தில் காட்சிப்படுத்தப்பட்டுள்ள ஒவ்வொரு வலைப்பக்கத்தின் நகலைச் சேமிக்கிறது. கேச் பிளக்கின் விற்பனையாளரிடமிருந்து தொழில்நுட்ப ஆதரவைப் பெறத் தேவைப்படுவதைத் தவிர, அனைத்து கேச் கோப்புகளும் தற்காலிகமானவை மற்றும் எந்த மூன்றாம் தரப்பினராலும் அணுகப்படாது. தள நிர்வாகியால் அமைக்கப்படும் அட்டவணையின்படி கேச் கோப்புகள் காலாவதியாகின்றன, ஆனால் தேவைப்பட்டால், இயற்கையான காலாவதிக்கு முன்பே நிர்வாகியால் அவற்றை எளிதாக நீக்க முடியும். உங்கள் தரவைத் தற்காலிகமாகச் செயலாக்க மற்றும் கேச் செய்ய நாங்கள் QUIC.cloud சேவைகளைப் பயன்படுத்தலாம்.','Please see %s for more details.'=>'மேலும் விவரங்களுக்கு %s ஐப் பார்க்கவும்.','Learn More'=>'மேலும் அறிக','Both full and partial strings can be used.'=>'முழு மற்றும் பகுதி சரங்கள் இரண்டையும் பயன்படுத்தலாம்.','Both full URLs and partial strings can be used.'=>'முழு URL-களையும் பகுதிச் சரங்களையும் (strings) பயன்படுத்தலாம்.','This setting will edit the .htaccess file.'=>'இந்த அமைப்பு .htaccess கோப்பைத் திருத்தும்.','The queue is processed asynchronously. It may take time.'=>'வரிசை முறை ஒத்திசைவற்ற முறையில் செயல்படுத்தப்படுகிறது. இதற்கு சிறிது நேரம் ஆகலாம்.','This feature needs an online generation service, which is not included in this plugin. The setting has no effect.'=>'இந்த அம்சத்திற்கு ஆன்லைன் உருவாக்கும் சேவை தேவைப்படுகிறது, இது இந்த செருகுநிரலில் (plugin) அடங்காது. இந்த அமைப்பிற்கு எந்தச் செயல்பாடும் இல்லை.','You have used all of your daily quota for today.'=>'இன்று உங்களுக்கான தினசரி ஒதுக்கீட்டை முழுமையாகப் பயன்படுத்திவிட்டீர்கள்.','Learn more or purchase additional quota.'=>'மேலும் அறியவும் அல்லது கூடுதல் ஒதுக்கீட்டை வாங்கவும்.','You have used all of your quota left for current service this month.'=>'இந்த மாதத்திற்கான நடப்பு சேவையின் உங்கள் ஒதுக்கீடு முழுவதையும் நீங்கள் பயன்படுத்திவிட்டீர்கள்.','You have too many requested images, please try again in a few minutes.'=>'நீங்கள் கோரிய படங்களின் எண்ணிக்கை மிக அதிகம், சில நிமிடங்களில் மீண்டும் முயற்சிக்கவும்.','You have images waiting to be pulled. Please wait for the automatic pull to complete, or pull them down manually now.'=>'இழுக்கப்படுவதற்காகக் காத்திருக்கும் படங்கள் உங்களிடம் உள்ளன. தானியங்கி இழுத்தல் செயல்முறை முடியும் வரை காத்திருக்கவும் அல்லது இப்போது அவற்றை நீங்களே கைமுறையாக இழுக்கவும்.','The image list is empty.'=>'படப் பட்டியல் காலியாக உள்ளது.','Not enough parameters. Please check if the QUIC.cloud connection is set correctly'=>'போதுமான அளவு அளபுருக்கள் (parameters) இல்லை. QUIC.cloud இணைப்பு சரியாக அமைக்கப்பட்டுள்ளதா எனச் சரிபார்க்கவும்','There is proceeding queue not pulled yet.'=>'இன்னும் இழுக்கப்படாத செயல்முறை வரிசை உள்ளது.','There is proceeding queue not pulled yet. Queue info: %s.'=>'இன்னும் எடுக்கப்படாத செயல் வரிசை ஒன்று உள்ளது. வரிசை தகவல்: %s.','The site is not a valid alias on QUIC.cloud.'=>'தளம் QUIC.cloud இல் செல்லுபடியாகும் மாற்றுப் பெயர் அல்ல.','The site is not registered on QUIC.cloud.'=>'தளம் QUIC.cloud இல் பதிவு செய்யப்படவில்லை.','The QUIC.cloud connection is not correct. Please try to sync your QUIC.cloud connection again.'=>'QUIC.cloud இணைப்பு சரியாக இல்லை. உங்கள் QUIC.cloud இணைப்பை மீண்டும் ஒத்திசைக்க முயற்சிக்கவும்.','The current server is under heavy load.'=>'தற்போதைய சேவையகம் அதிக சுமைக்கு உட்பட்டுள்ளது.','Online node needs to be redetected.'=>'ஆன்லைன் நோடை மீண்டும் கண்டறிய வேண்டும்.','Credits are not enough to proceed the current request.'=>'தற்போதைய கோரிக்கையைத் தொடர கிரெடிட்கள் போதாது.','%s file not writable.'=>'%s கோப்பு எழுதக்கூடியதாக இல்லை.','Could not find %1$s in %2$s.'=>'%2$s இல் %1$s ஐக் கண்டுபிடிக்க முடியவில்லை.','Invalid login cookie. Please check the %s file.'=>'தவறான லாகின் கூகி. %s கோப்பினைச் சரிபார்க்கவும்.','Failed to back up %s file, aborted changes.'=>'%s கோப்பின் காப்புப் பிரதி எடுப்பது தோல்வியடைந்தது, மாற்றங்கள் கைவிடப்பட்டன.','%s file not readable.'=>'%s கோப்பை படிக்க முடியவில்லை.','Failed to get %s file contents.'=>'%s கோப்பு உள்ளடக்கங்களைப் பெறுவதில் தோல்வி ஏற்பட்டது.','Failed to create table %1$s! SQL: %2$s.'=>'%1$s அட்டவணையை உருவாக்குவதில் தோல்வி! SQL: %2$s.','Crawler disabled by the server admin.'=>'சேவையக நிர்வாகியால் ஊர்ந்துசெல்பவர் முடக்கப்பட்டுள்ளது.','Previous request too recent. Please try again later.'=>'முந்தைய கோரிக்கை மிகவும் சமீபத்தில்தான் கொடுக்கப்பட்டுள்ளது. சிறிது நேரம் கழித்து மீண்டும் முயற்சிக்கவும்.','Previous request too recent. Please try again after %s.'=>'முந்தைய கோரிக்கை மிகவும் சமீபத்தில்தான் கொடுக்கப்பட்டுள்ளது. தயவுசெய்து %s கழித்து மீண்டும் முயற்சிக்கவும்.','Your application is waiting for approval.'=>'உங்கள் விண்ணப்பம் ஒப்புதலுக்காகக் காத்திருக்கிறது.','The callback validation to your domain failed due to hash mismatch.'=>'ஹேஷ் பொருந்தாததால் உங்கள் டொமைனுக்கான கால்பேக் சரிபார்ப்பு தோல்வியடைந்தது.','The callback validation to your domain failed. Please make sure there is no firewall blocking our servers.'=>'உங்கள் டொமைனுக்கான கால்பேக் (callback) சரிபார்ப்பு தோல்வியடைந்தது. எங்கள் சர்வர்களைத் தடுக்கும் ஃபயர்வால்கள் (firewall) எதுவும் இல்லை என்பதை உறுதிப்படுத்தவும்.','The callback validation to your domain failed. Please make sure there is no firewall blocking our servers. Response code: '=>'உங்கள் டொமைனுக்கான கால்பேக் (callback) சரிபார்ப்பு தோல்வியடைந்தது. எங்கள் சர்வர்களைத் தடுக்கும் ஃபயர்வாள் (firewall) எதுவும் இல்லை என்பதை உறுதிப்படுத்திக் கொள்ளவும். பதில் குறியீடு:','Your domain has been forbidden from using our services due to a previous policy violation.'=>'முந்தைய கொள்கை மீறல் காரணமாக உங்களது டொமைன் எங்கள் சேவைகளைப் பயன்படுத்துவதிலிருந்து தடை செய்யப்பட்டுள்ளது.','You cannot remove this DNS zone, because it is still in use. Please update the domain\'s nameservers, then try to delete this zone again, otherwise your site will become inaccessible.'=>'இந்த DNS மண்டலம் இன்னும் பயன்பாட்டில் இருப்பதால் உங்களால் இதை அகற்ற முடியாது. டொமைனின் நேம் சர்வர்களை (nameservers) புதுப்பித்துவிட்டு, இந்த மண்டலத்தை மீண்டும் நீக்க முயற்சிக்கவும், இல்லையெனில் உங்கள் தளம் அணுக முடியாததாகிவிடும்.','Unknown error'=>'தெரியாத பிழை','Filename is empty!'=>'கோப்புப் பெயர் காலியாக உள்ளது!','Folder does not exist: %s'=>'கோப்புறை இருக்கவில்லை: %s','Can not create folder: %1$s. Error: %2$s'=>'கோப்புறையை உருவாக்க முடியவில்லை: %1$s. பிழை: %2$s','Folder is not writable: %s.'=>'கோப்புறை எழுதக்கூடியது அல்ல: %s.','File %s is not writable.'=>'கோப்பு %s எழுதக்கூடியதல்ல.','Failed to write to %s.'=>'%s-ல் எழுதுவது தோல்வியடைந்தது.','Guest Mode lists synced successfully.'=>'விருந்தினர் முறைமை பட்டியல்கள் வெற்றிகரமாக ஒத்திசைக்கப்பட்டன.','Failed to sync Guest Mode lists.'=>'விருந்தினர் முறை பட்டியல்களை ஒத்திசைப்பதில் தோல்வி ஏற்பட்டது.','%1$s %2$s files left in queue'=>'வரிசையில் இன்னும் %1$s %2$s கோப்புகள் உள்ளன','Cancel'=>'ரத்துசெய்','Purge this page'=>'இந்தப் பக்கத்தை அழிக்கவும்','Mark this page as '=>'இந்தப் பக்கத்தைக் குறிக்கவும்','Forced cacheable'=>'கட்டாயமாக தற்காலிக சேமிப்பில் வைக்கக்கூடியது','Non cacheable'=>'கேச் செய்ய முடியாதவை','Private cache'=>'தனிப்பட்ட தற்காலிக சேமிப்பு','No optimization'=>'உகப்பாக்கம் இல்லை','More settings'=>'மேலும் அமைப்புகள்','Purge All'=>'அனைத்தையும் நீக்கு','LSCache'=>'LSCache','CSS/JS Cache'=>'CSS/JS தற்காலிக சேமிப்பு','Cloudflare'=>'Cloudflare','Object Cache'=>'ஆப்ஜெக்ட் கேச்','Opcode Cache'=>'ஆப்கோட் கேச்','Localized Resources'=>'உள்ளூர்மயமாக்கப்பட்ட வளங்கள்','LQIP Cache'=>'LQIP தற்காலிக சேமிப்பு','Gravatar Cache'=>'Gravatar கேச்','Enable All Features'=>'அனைத்து அம்சங்களையும் இயக்கு','Zinn® Cache Engine Purge All'=>'Zinn® கேச் என்ஜின் அனைத்தையும் அழி (Purge All)','Manage'=>'நிர்வகி','Remove all previous unfinished image optimization requests.'=>'முந்தைய அனைத்து முழுமையடையாத பட மேம்படுத்தல் கோரிக்கைகளையும் அகற்றவும்.','Clean Up Unfinished Data'=>'முடிவுறாத தரவை அகற்று','Install %s'=>'%s ஐ நிறுவுங்கள்','Install Now'=>'இப்போது நிறுவுங்கள்','<a href="%1$s" %2$s>View version %3$s details</a> or <a href="%4$s" %5$s target="_blank">update now</a>.'=>'<a href="%1$s" %2$s>பதிப்பு %3$s விவரங்களைக் காண்க</a> அல்லது <a href="%4$s" %5$s target="_blank">இப்போதே புதுப்பிக்கவும்</a>.','View %1$s version %2$s details'=>'%1$s பதிப்பு %2$s விவரங்களைக் காண்க','Update %s now'=>'%s ஐ இப்போதே புதுப்பிக்கவும்','Mobile Agent Rules'=>'மொபைல் முகவர் விதிகள்','<p>Please add/replace the following codes into the beginning of %1$s:</p> %2$s'=>'<p>%1$s இன் தொடக்கத்தில் பின்வரும் குறியீடுகளைச் சேர்க்கவும்/மாற்றவும்:</p> %2$s','Cleaned up unfinished data successfully.'=>'முடிக்கப்படாத தரவு வெற்றிகரமாகச் சுத்தம் செய்யப்பட்டது.','Reset image optimization counter successfully.'=>'பட உகப்பாக்க கவுண்டர் வெற்றிகரமாக மீட்டமைக்கப்பட்டது.','Destroy all optimization data successfully.'=>'அனைத்து உகப்பாக்க தரவுகளும் வெற்றிகரமாக அழிக்கப்பட்டன.','Rescanned successfully.'=>'மீண்டும் ஸ்கேன் செய்யப்பட்டது.','Rescanned %d images successfully.'=>'%d படங்களின் ஸ்கேன் வெற்றிகரமாக மீண்டும் செய்யப்பட்டது.','Calculated backups successfully.'=>'கணக்கிடப்பட்ட காப்புப்பிரதிகள் வெற்றிகரமாக முடிக்கப்பட்டன.','Removed backups successfully.'=>'நீக்கப்பட்ட காப்புப்பிரதிகள் வெற்றிகரமாக.','Switched images successfully.'=>'படங்கள் வெற்றிகரமாக மாற்றப்பட்டன.','Switched to optimized file successfully.'=>'உகந்த கோப்புக்கு வெற்றிகரமாக மாற்றப்பட்டது.','Disabled WebP file successfully.'=>'வெப்ஜி (WebP) கோப்பு வெற்றிகரமாக முடக்கப்பட்டது.','Enabled WebP file successfully.'=>'வெப்ஈபி (WebP) கோப்பு வெற்றிகரமாக இயக்கப்பட்டது.','Disabled AVIF file successfully.'=>'AVIF கோப்பு வெற்றிகரமாக முடக்கப்பட்டது.','Enabled AVIF file successfully.'=>'AVIF கோப்பு வெற்றிகரமாக இயக்கப்பட்டது.','Restored original file successfully.'=>'மூலக் கோப்பு வெற்றிகரமாக மீட்டெடுக்கப்பட்டது.','Reset the optimized data successfully.'=>'உகந்ததாக்கப்பட்ட தரவு வெற்றிகரமாக மீட்டமைக்கப்பட்டது.','Started async image optimization request'=>'ஒத்திசைவற்ற பட உகப்பாக்க கோரிக்கை தொடங்கப்பட்டது','Pull Cron is running'=>'புல் க்ரான் இயங்குகிறது','Some optimized image file(s) has expired and was cleared.'=>'சில உகந்தமாக்கப்பட்ட படக் கோப்பு(கள்) காலாவதியாகிவிட்டன மற்றும் அகற்றப்பட்டன.','Pulled WebP image md5 does not match the notified WebP image md5.'=>'பதிவிறக்கம் செய்யப்பட்ட WebP படத்தின் md5 ஆனது அறிவிக்கப்பட்ட WebP படத்தின் md5 உடன் பொருந்தவில்லை.','Pulled AVIF image md5 does not match the notified AVIF image md5.'=>'எடுக்கப்பட்ட AVIF பட md5 ஆனது அறிவிக்கப்பட்ட AVIF பட md5 உடன் பொருந்தவில்லை.','One or more pulled images does not match with the notified image md5'=>'இழுக்கப்பட்ட ஒன்று அல்லது அதற்கு மேற்பட்ட படங்கள் அறிவிக்கப்பட்ட பட md5 உடன் பொருந்தவில்லை','Pushed %1$s to Cloud server, accepted %2$s.'=>'%1$s கிளவுட் சர்வரில் தள்ளப்பட்டது, %2$s ஏற்கப்பட்டது.','Cleared %1$s invalid images.'=>'%1$s தவறான படங்கள் அழிக்கப்பட்டன.','No valid image found in the current request.'=>'நடப்பு கோரிக்கையில் சரியான படம் எதுவும் கிடைக்கவில்லை.','No valid image found by Cloud server in the current request.'=>'தற்போதைய கோரிக்கையில் கிளவுட் சேவையகம் மூலம் சரியான படம் எதுவும் கண்டறியப்படவில்லை.','Import failed due to file error.'=>'கோப்புப் பிழை காரணமாக இறக்குமதி தோல்வியுற்றது.','Imported setting file %s successfully.'=>'%s இறக்குமதி செய்யப்பட்ட அமைப்புகள் கோப்பு வெற்றிகரமாகப் பெறப்பட்டது.','Reset successfully.'=>'வெற்றிகரமாக மீட்டமைக்கப்பட்டது.','Images not requested'=>'படங்கள் கோரப்படவில்லை','Images ready to request'=>'கோரிக்கை அனுப்பத்